import type { Token, TokenSchema } from './extract'
import { resolveValue } from './extract'
import schemaJson from './payload-theme-schema.json'

// Generated by `pnpm extract-payload-theme` — never hand-edit the JSON.
export const schema = schemaJson as TokenSchema

export const TOKENS: Record<string, Token> = Object.fromEntries(schema.tokens.map((t) => [t.var, t]))

/** Payload's default ramps: family → step → hex/rgba */
export const DEFAULT_RAMPS = schema.ramps

export const rampVar = (family: string, step: string) => `--ramp-${family}-${step}`

/** Payload's default value for a token in a mode (dark falls back to light). */
export function defaultValue(varName: string, mode: 'light' | 'dark'): string | undefined {
  const t = TOKENS[varName]
  if (!t) return undefined
  return mode === 'dark' ? (t.dark ?? t.light) : t.light
}

/**
 * Resolves a token to a concrete value for a mode, applying theme overrides on top of
 * Payload's defaults. Used by the editor to show swatches and contrast ratios.
 */
export function resolveToken(
  varName: string,
  mode: 'light' | 'dark',
  overrides: { ramps: Record<string, string>; light: Record<string, string>; dark: Record<string, string> },
): string {
  const values: Record<string, string> = {}
  for (const t of schema.tokens) values[t.var] = mode === 'dark' ? (t.dark ?? t.light) : t.light
  Object.assign(values, overrides.ramps)
  for (const [v, value] of Object.entries(overrides.light)) {
    // A light override only reaches dark mode when Payload has no separate dark value (see css.ts)
    if (mode === 'light' || !TOKENS[v]?.dark) values[v] = value
  }
  if (mode === 'dark') Object.assign(values, overrides.dark)
  return resolveValue(values[varName] ?? `var(${varName})`, values)
}
